    reparsed = Marker(str(m))
    for env in (
        {"python_version": "3.12", "sys_platform": "darwin"},
        {"python_version": "3.12", "sys_platform": "linux"},
        {"python_version": "3.9", "sys_platform": "darwin"},
    ):
